	case DATA_FORMAT_R16_UNORM:
	case DATA_FORMAT_R16_SNORM:
	case DATA_FORMAT_R16_UINT:
	case DATA_FORMAT_R16_SINT:
	case DATA_FORMAT_R16_SFLOAT:
