	case DATA_FORMAT_R32G32B32A32_UINT:
	case DATA_FORMAT_R32G32B32A32_SINT:
	case DATA_FORMAT_R32G32B32A32_SFLOAT:
		return 16;
	case DATA_FORMAT_R64_UINT:
	case DATA_FORMAT_R64_SINT:
	case DATA_FORMAT_R64_SFLOAT:
