String ShaderLanguage::get_operator_text(Operator p_op)
{
	static const char* op_names[OP_MAX] = {"==", "!=", "<", "<=", ">", ">=", "&&", "||", "!", "-",
		"+", "-", "*", "/", "%", "<<", ">>", "=",
		"+=", "-=", "*=", "/=", "%=", "<<=", ">>=", "&=", "|=", "^=", "&", "|", "^", "~", "++",
		"--", "?", ":", "++", "--", "()", "construct", "index", "empty"};

	return op_names[p_op];
}

